import Path = require('path')
import type { Response } from 'express'
import Logger = require('../Logger')
import archiver = require('../libs/archiver')

// Only the members of the vendored archive object (server/libs/archiver/lib/core.js) that this file uses
type ZipArchive = {
  pointer(): number
  on(event: string, listener: (err: NodeJS.ErrnoException) => void): unknown
  pipe(destination: Response): unknown
  directory(dirpath: string, destpath: string | false): unknown
  file(filepath: string, data: { name: string }): unknown
  finalize(): unknown
}
// server/libs/archiver is tagged @constructor in its JSDoc, so its inferred type can only be called with new; at runtime it is a plain function that returns the archive
type ArchiverFactory = (format: string, options: { zlib: { level: number } }) => ZipArchive

const zipDirectoryPipe = (path: string, filename: string, res: Response): Promise<void> => {
  return new Promise((resolve, reject) => {
    // create a file to stream archive data to
    res.attachment(filename)

    // boundary cast: the inferred type of the vendored archiver is not callable (see ArchiverFactory)
    const archive = (archiver as ArchiverFactory)('zip', {
      zlib: { level: 0 } // Sets the compression level.
    })

    // listen for all archive data to be written
    // 'close' event is fired only when a file descriptor is involved
    res.on('close', () => {
      Logger.info(archive.pointer() + ' total bytes')
      Logger.debug('archiver has been finalized and the output file descriptor has closed.')
      resolve()
    })

    // This event is fired when the data source is drained no matter what was the data source.
    // It is not part of this library but rather from the NodeJS Stream API.
    // @see: https://nodejs.org/api/stream.html#stream_event_end
    res.on('end', () => {
      Logger.debug('Data has been drained')
    })

    // good practice to catch warnings (ie stat failures and other non-blocking errors)
    archive.on('warning', function (err) {
      if (err.code === 'ENOENT') {
        // log warning
        Logger.warn(`[DownloadManager] Archiver warning: ${err.message}`)
      } else {
        // throw error
        Logger.error(`[DownloadManager] Archiver error: ${err.message}`)
        // throw err
        reject(err)
      }
    })
    archive.on('error', function (err) {
      Logger.error(`[DownloadManager] Archiver error: ${err.message}`)
      reject(err)
    })

    // pipe archive data to the file
    archive.pipe(res)

    archive.directory(path, false)

    archive.finalize()
  })
}

/**
 * Creates a zip archive containing multiple directories and streams it to the response.
 *
 * @param {{ path: string, isFile: boolean }[]} pathObjects
 * @param {string} filename - Name of the zip file to be sent as attachment.
 * @param {Response} res - Response object to pipe the archive data to.
 * @returns {Promise<void>} - Promise that resolves when the zip operation completes.
 */
