 */
function rawProbe(filepath) {
  if (process.env.FFPROBE_PATH) {
    ffprobe.FFPROBE_PATH = process.env.FFPROBE_PATH
  }

  return ffprobe(filepath).catch((err) => {
    return {
      error: err
    }
  })
}
module.exports.rawProbe = rawProbe

